{"implementation":"import collections
def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    retained = set(node_map.keys())
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if not node['removable']:
            continue
        if nid == 'root':
            continue
        if node['symbol'] in required_symbols:
            continue
        # check retained children
        if any(c in retained for c in children[nid]):
            continue
        retained.remove(nid)
        removed.append(nid)
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"}
